import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def check_property(n):
    if n < 2:
        return False

    # We only need to check k in the range 1 <= k < n
    for k in range(1, n):
        if gcd(k, n) == 1:
            # Check if k^2 mod n == 1
            if (k * k) % n != 1:
                # Found a counterexample
                return False
    # If no counterexample was found for all k coprime to n
    return True

results = {}
for n in range(2, 11):
    results[n] = check_property(n)

satisfying_n = [n for n, satisfies in results.items() if satisfies]

print(f"Results for n=2 to 10: {results}")
print(f"Numbers satisfying the property: {satisfying_n}")
